/**
 * Private row → domain mappers for the repository layer.
 *
 * SQLite stores branded ids as plain text and collections as JSON strings, so
 * exactly one place is allowed to re-apply the brands and parse the JSON: here.
 * Services never see a `*Row` type.
 */
import type {
  ActivityEventRow,
  AttachmentRow,
  CommentRow,
  InvitationRow,
  InvoiceRow,
  IssueRow,
  LabelRow,
  MemberRow,
  NotificationPreferenceRow,
  NotificationRow,
  OrganizationRow,
  OrganizationUsageRow,
  ProjectRow,
  SubscriptionRow,
  UserRow,
} from "@/server/db";
import type {
  ActivityAction,
  ActivityEvent,
} from "@/types/activity";
import type { Invoice, Subscription } from "@/types/billing";
import type { Comment } from "@/types/comment";
import type {
  ActivityId,
  AttachmentId,
  CommentId,
  InvitationId,
  IsoTimestamp,
  IssueId,
  LabelId,
  MemberId,
  NotificationId,
    name: row.name,
    avatarUrl: row.avatarUrl,
    timezone: row.timezone,
    emailVerifiedAt: brandStampOrNull(row.emailVerifiedAt),
    createdAt: brandStamp(row.createdAt),
    updatedAt: brandStamp(row.updatedAt),
  };
}

export function toOrganization(row: OrganizationRow): Organization {
  return {
    id: brandId<OrgId>(row.id),
    name: row.name,
    slug: row.slug,
    ownerId: brandId<UserId>(row.ownerId),
    plan: row.plan,
    logoUrl: row.logoUrl,
    trialEndsAt: brandStampOrNull(row.trialEndsAt),
    settings: {
      defaultIssueStatus: row.defaultIssueStatus,
      allowPublicProjects: row.allowPublicProjects,
      requireTwoFactor: row.requireTwoFactor,
      digestHourUtc: row.digestHourUtc,
      enabledFlagOverrides: parseJsonArray<string>(row.enabledFlagOverrides),
    },
    createdAt: brandStamp(row.createdAt),
    updatedAt: brandStamp(row.updatedAt),
    archivedAt: brandStampOrNull(row.archivedAt),
  };
}

export function toUsage(row: OrganizationUsageRow): OrganizationUsage {
  return {
    orgId: brandId<OrgId>(row.orgId),
    seatsUsed: row.seatsUsed,
    projectsUsed: row.projectsUsed,
    issuesUsed: row.issuesUsed,
    storageMbUsed: row.storageMbUsed,
    measuredAt: brandStamp(row.measuredAt),
  };
}
/**
 * Server-side flag context construction and the org-level override toggle.
 *
 * Must call (do not reimplement): assertCan, isEnabled, snapshotFlags, emit
 */
import { emit } from "@/lib/event-bus";
import { isEnabled, snapshotFlags } from "@/lib/feature-flags";
import { assertCan } from "@/lib/permissions";
import { getFlagDefinition } from "@/config/feature-flags";
import * as orgRepo from "@/server/repositories/organization-repository";
import { actorEnvelope, orgResource, requireFound } from "./_support";
import type { ToggleFeatureFlagInput } from "@/schemas/feature-flag";
import type { FeatureFlagSnapshot, FlagContext } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { Organization } from "@/types/organization";

/**
 * Builds the evaluation context every `isEnabled()` call needs. Both halves
 * are nullable so marketing pages — no session, no org — can still ask about
 * a flag and get the free-plan answer.
 */
export function buildFlagContext(
  actor: Actor | null,
  org: Organization | null,
): FlagContext {
  return {
    orgId: org?.id ?? actor?.orgId ?? null,
